    return max_val

def find_min(arr):
    min_val = arr[0]
    for i in range(1, len(arr)):
        if arr[i] < min_val:
            min_val = arr[i]
    return min_val

def find_median(arr):
    sorted_arr = sorted(arr)
    if len(sorted_arr) % 2 == 0:
        median = (sorted_arr[len(sorted_arr)//2] + sorted_arr[len(sorted_arr)//2 - 1]) / 2
    else:
        median = sorted_arr[len(sorted_arr)//2]
    return median

def find_mode(arr):
    count_dict = {}
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1
