def calculate_statistics(arr):
    """
    Calculate the maximum, minimum, median, and mode of an array.

    :param arr: List of numbers
    :return: A dictionary containing 'max', 'min', 'median', and 'mode' keys
    """
    stats = {
        'max': max(arr),
        'min': min(arr),
        'median': median(arr),
        'mode': mode(arr)
    }
    return stats

def median(arr):
    sorted_arr = sorted(arr)
    n = len(sorted_arr)
    if n % 2 == 0:
        return (sorted_arr[n//2] + sorted_arr[n//2 - 1]) / 2
    else:
        return sorted_arr[n//2]

def mode(arr):
    count_dict = {num: arr.count(num) for num in set(arr)}
    max_count = max(count_dict.values())
    mode = [num for num, count in count_dict.items() if count == max_count]
    return mode
```

